import datetime
import unittest

from . import tomllib


class TestOptionalSeconds(unittest.TestCase):
    def test_local_time_without_seconds(self):
        self.assertEqual(tomllib.loads("t = 13:37"), {"t": datetime.time(13, 37)})

    def test_local_time_boundaries_without_seconds(self):
        self.assertEqual(
            tomllib.loads("a = 00:00\nb = 23:59\n"),
            {"a": datetime.time(0, 0), "b": datetime.time(23, 59)},
        )

    def test_local_datetime_without_seconds(self):
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27T07:32"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32)},
        )

    def test_local_datetime_space_separator_without_seconds(self):
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27 07:32"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32)},
        )

    def test_offset_datetime_zulu_without_seconds(self):
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27T07:32Z"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32, tzinfo=datetime.timezone.utc)},
        )

    def test_offset_datetime_numeric_offset_without_seconds(self):
        tz = datetime.timezone(datetime.timedelta(hours=-7))
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27T07:32-07:00"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32, tzinfo=tz)},
        )
        tz = datetime.timezone(datetime.timedelta(hours=5, minutes=30))
        self.assertEqual(
            tomllib.loads("dt = 1979-05-27T07:32+05:30"),
            {"dt": datetime.datetime(1979, 5, 27, 7, 32, tzinfo=tz)},
        )

    def test_without_seconds_in_array_and_inline_table(self):
        self.assertEqual(
            tomllib.loads("a = [13:37, 1979-05-27T07:32]\nb = {t = 08:05}\n"),
            {
                "a": [datetime.time(13, 37), datetime.datetime(1979, 5, 27, 7, 32)],
                "b": {"t": datetime.time(8, 5)},
            },
        )

    def test_seconds_still_accepted(self):
        self.assertEqual(
            tomllib.loads("t = 13:37:42.5\ndt = 1979-05-27T07:32:01Z\n"),
            {
                "t": datetime.time(13, 37, 42, 500000),
                "dt": datetime.datetime(
                    1979, 5, 27, 7, 32, 1, tzinfo=datetime.timezone.utc
                ),
            },
        )

    def test_fraction_without_seconds_is_invalid(self):
        for doc in ("t = 13:37.5", "dt = 1979-05-27T07:32.5"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_malformed_times_still_invalid(self):
        for doc in (
            "t = 13:37:",
            "t = 13:3",
            "t = 24:00",
            "t = 13:60",
            "t = 13:37:60",
            "dt = 1979-05-27T07",
            "dt = 1979-05-27T07:32:",
        ):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)


