import unittest

from . import tomllib


class TestInlineTableNewlinesAndTrailingComma(unittest.TestCase):
    def test_trailing_comma_single_line(self):
        self.assertEqual(tomllib.loads("t = { c = 1, }"), {"t": {"c": 1}})
        self.assertEqual(tomllib.loads("t = {c=1,}"), {"t": {"c": 1}})
        self.assertEqual(
            tomllib.loads("t = { a = 1, b = 2 , }"), {"t": {"a": 1, "b": 2}}
        )

    def test_newlines_between_pairs(self):
        doc = "t = {\n  a = 1,\n  b = 2\n}\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_newline_only_after_open_brace(self):
        self.assertEqual(tomllib.loads("t = {\na = 1}"), {"t": {"a": 1}})

    def test_newline_only_before_close_brace(self):
        self.assertEqual(tomllib.loads("t = {a = 1\n}"), {"t": {"a": 1}})

    def test_newline_before_comma(self):
        doc = "t = {a = 1\n, b = 2}"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_newlines_and_trailing_comma(self):
        doc = "t = {\n\ta = 1,\n\tb = 2,\n}\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})
        doc = "t = {\na = 1,\nb = 2,}"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_newline_between_trailing_comma_and_close_brace(self):
        self.assertEqual(tomllib.loads("t = {a = 1,\n\n}"), {"t": {"a": 1}})

    def test_empty_table_with_newlines(self):
        self.assertEqual(tomllib.loads("t = {\n}"), {"t": {}})
        self.assertEqual(tomllib.loads("t = {\n\n  \n}"), {"t": {}})

    def test_crlf_newlines(self):
        doc = "t = {\r\n  a = 1,\r\n  b = 2,\r\n}\r\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_comments_inside(self):
        doc = (
            "t = {#comment\n"
            "\t# comment\n"
            "\tc = 1,#comment\n"
            "\t#comment\n"
            "}#comment\n"
        )
        self.assertEqual(tomllib.loads(doc), {"t": {"c": 1}})

    def test_comment_before_comma(self):
        doc = "t = {a = 1 # comment\n, b = 2}"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1, "b": 2}})

    def test_nested_tables_and_arrays(self):
        doc = (
            "tbl = {\n"
            '\thello = "world",\n'
            "\t1     = 2,\n"
            "\tarr   = [1,\n"
            "\t         2,\n"
            "\t        ],\n"
            "\ttbl = {\n"
            "\t\t k = 1,\n"
            "\t}\n"
            "}\n"
        )
        self.assertEqual(
            tomllib.loads(doc),
            {"tbl": {"hello": "world", "1": 2, "arr": [1, 2], "tbl": {"k": 1}}},
        )

    def test_inline_table_in_array(self):
        doc = "a = [{\n  x = 1,\n}, { y = 2, }]"
        self.assertEqual(tomllib.loads(doc), {"a": [{"x": 1}, {"y": 2}]})

    def test_statement_after_multiline_table(self):
        doc = "t = {\n  a = 1,\n}\nb = 2\n"
        self.assertEqual(tomllib.loads(doc), {"t": {"a": 1}, "b": 2})

    def test_lone_comma_still_invalid(self):
        self.assertEqual(tomllib.loads("t = {a = 1,}"), {"t": {"a": 1}})
        for doc in ("t = {,}", "t = {\n,\n}", "t = {,"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_double_comma_still_invalid(self):
        self.assertEqual(tomllib.loads("t = {a = 1,}"), {"t": {"a": 1}})
        for doc in ("t = {a = 1,,}", "t = {a = 1,\n,}", "t = {a = 1,, b = 2}"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_newline_does_not_replace_comma(self):
        self.assertEqual(
            tomllib.loads("t = {\na = 1,\nb = 2\n}"), {"t": {"a": 1, "b": 2}}
        )
        with self.assertRaises(tomllib.TOMLDecodeError):
            tomllib.loads("t = {\na = 1\nb = 2\n}")

    def test_newline_inside_key_value_pair_still_invalid(self):
        self.assertEqual(tomllib.loads("t = {\na = 1\n}"), {"t": {"a": 1}})
        for doc in ("t = {a =\n1}", "t = {a\n= 1}"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_unclosed_still_invalid(self):
        self.assertEqual(tomllib.loads("t = {a = 1,\n}"), {"t": {"a": 1}})
        for doc in ("t = {\n", "t = {a = 1,\n", "t = {a = 1\n", "t = {a = 1,"):
            with self.subTest(doc=doc):
                with self.assertRaises(tomllib.TOMLDecodeError):
                    tomllib.loads(doc)

    def test_duplicate_key_across_lines_still_invalid(self):
        self.assertEqual(
            tomllib.loads("t = {\na = 1,\nb = 2,\n}"), {"t": {"a": 1, "b": 2}}
        )
        with self.assertRaises(tomllib.TOMLDecodeError):
            tomllib.loads("t = {\na = 1,\na = 2,\n}")
